-- Single transaction: all 81 writes (1 update + 80 inserts) commit
-- together or not at all, so no intermediate state (e.g. a session
-- moved to a new time slot while another session hasn't been inserted
-- yet) can ever produce a transient real room/time conflict mid-apply.

begin;

-- Safety guard: fail loudly if the live schema's reference-data ids
-- have shifted since this migration was generated.
do $$
declare
  v_d1_count int;
  v_total_count int;
begin
  select count(*) into v_d1_count from sessions where session_code ilike 'D1-%';
  if v_d1_count <> 32 then
    raise exception 'Expected exactly 32 existing D1-* sessions before this migration, found %', v_d1_count;
  end if;

  select count(*) into v_total_count from sessions;
  if v_total_count <> 32 then
    raise exception 'Expected exactly 32 total sessions before this migration, found %', v_total_count;
  end if;
end $$;

